export function dedupe(words: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const word of words) {
    if (!seen.has(word)) {
      seen.add(word);
      out.push(word);
    }
  }
  return out;
}

export function dedupe(words: string[]): string[] {
  const seen: Record<string, boolean> = {};
  const out: string[] = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (!Object.prototype.hasOwnProperty.call(seen, word)) {
      seen[word] = true;
      out.push(word);
    }
  }

  return out;
}

export function dedupe(words: string[]): string[] {
