export function medianFloor(xs: number[]): number {
  const n = xs.length;
  if (n === 0) {
    throw new Error("median of empty array");
  }

  const values = xs.slice();
  const target = Math.floor(n / 2);
  let lo = 0;
  let hi = n - 1;

  while (lo < hi) {
    const pivot = values[Math.floor((lo + hi) / 2)];
    let i = lo;
    let j = hi;

    while (i <= j) {
      while (values[i] < pivot) i++;
      while (values[j] > pivot) j--;
      if (i <= j) {
        const value = values[i];
        values[i] = values[j];
        values[j] = value;
        i++;
        j--;
      }
    }

    if (target <= j) {
      hi = j;
    } else if (target >= i) {
      lo = i;
    } else {
      break;
    }
  }

  if (n % 2 === 1) {
    return values[target];
  }

  let left = values[0];
  for (let i = 1; i < target; i++) {
    if (values[i] > left) left = values[i];
  }
  return Math.floor((left + values[target]) / 2);
}

