export function medianFloor(xs: number[]): number {
  const n = xs.length;
  if (n === 0) {
    throw new Error("median of empty array");
  }

  const values = xs.slice();
  const target = Math.floor(n / 2);

  // In-place quickselect on the copy: partition until the middle order
  // statistic is in place. The argument itself remains unchanged.
  let left = 0;
  let right = n - 1;
  while (left < right) {
    const pivot = values[Math.floor((left + right) / 2)];
    let i = left;
    let j = right;

    while (i <= j) {
      while (values[i] < pivot) i++;
      while (values[j] > pivot) j--;
      if (i <= j) {
        const tmp = values[i];
        values[i] = values[j];
        values[j] = tmp;
        i++;
        j--;
      }
    }

    if (target <= j) {
      right = j;
    } else if (target >= i) {
      left = i;
    } else {
      break;
    }
  }

  const upper = values[target];
  if (n % 2 === 1) {
    return upper;
  }

  let lower = values[0];
  for (let k = 1; k < target; k++) {
    if (values[k] > lower) lower = values[k];
  }
  return Math.floor((lower + upper) / 2);
}

