export function sortPointsByY(
  points: { x: number; y: number }[],
): { x: number; y: number }[] {
  const n = points.length;
  const result = points.slice();
  if (n < 2) return result;

  let source = result;
  let target = new Array<{ x: number; y: number }>(n);

  for (let width = 1; width < n; width *= 2) {
    for (let start = 0; start < n; start += width * 2) {
      const mid = Math.min(start + width, n);
      const end = Math.min(start + width * 2, n);
      let left = start;
      let right = mid;
      let out = start;

      while (left < mid && right < end) {
        if (source[left].y <= source[right].y) {
          target[out++] = source[left++];
        } else {
          target[out++] = source[right++];
        }
      }
      while (left < mid) target[out++] = source[left++];
      while (right < end) target[out++] = source[right++];
    }
    const swap = source;
    source = target;
    target = swap;
  }

  return source;
}

