export function spread(
  xs: number[],
): { count: number; min: number; max: number; range: number } | null {
  const n = xs.length;
  if (n === 0) {
    return null;
  }

  let lo = xs[0];
  let hi = xs[0];
  let i = 1;
  for (; i + 1 < n; i += 2) {
    const a = xs[i];
    const b = xs[i + 1];
    if (a < b) {
      if (a < lo) lo = a;
      if (b > hi) hi = b;
    } else {
      if (b < lo) lo = b;
      if (a > hi) hi = a;
    }
  }
  if (i < n) {
    const x = xs[i];
    if (x < lo) lo = x;
    if (x > hi) hi = x;
  }

  return { count: n, min: lo, max: hi, range: hi - lo };
}

