export function twoSum(xs: number[], target: number): [number, number] | null {
  const firstIndexByValue: Record<string, number> = {};

  for (let j = 0; j < xs.length; j++) {
    const complement = target - xs[j];
    const i = firstIndexByValue[String(complement)];
    if (i !== undefined) {
      return [i, j];
    }

    const key = String(xs[j]);
    if (firstIndexByValue[key] === undefined) {
      firstIndexByValue[key] = j;
    }
  }

  return null;
}

