export function aliquotSum(n: number): number {
  if (n <= 1) return 0;

  let sum = 1;
  for (let i = 2; i <= Math.floor(n / i); i++) {
    if (n % i === 0) {
      sum += i;
      const paired = n / i;
      if (paired !== i && paired !== n) sum += paired;
    }
  }
  return sum;
}

