export function factorial(n: number): number {
  if (n < 0) {
    throw new Error("factorial of a negative number");
  }
  if (n > 18) {
    return Infinity;
  }
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

export function collatzSteps(n: number, maxSteps: number): number {
  if (n < 1) {
    throw new Error("n must be a positive integer");
  }
  if (n === 1) {
    return 0;
  }
  let x = n;
  let step = 0;
  while (step < maxSteps) {
    step++;
    x = x % 2 === 0 ? x / 2 : 3 * x + 1;
    if (x === 1) {
      return step;
    }
  }
  throw new Error("step limit exceeded");
}

