export function digitSum(value: number): number {
  let n = Math.abs(value);
  let sum = 0;
  while (n >= 1000) {
    sum += n % 10;
    n = Math.floor(n / 10);
    sum += n % 10;
    n = Math.floor(n / 10);
    sum += n % 10;
    n = Math.floor(n / 10);
  }
  while (n > 0) {
    sum += n % 10;
    n = Math.floor(n / 10);
  }
  return sum;
}

export function digitSum(value: number): number {
  let n = Math.abs(value);
  let sum = 0;
  while (n >= 10) {
    const q = Math.floor(n / 10);
    sum += n - q * 10;
    n = q;
  }
  return sum + n;
}

export function floorDivMod(a: number, b: number): [number, number] {
  if (b === 0) {
    throw new Error("division by zero");
  }
  const q = Math.floor(a / b);
  return [q, a - q * b];
