export function reverseDigits(n: number, acc: number): number {
  if (n < 0) {
    throw new Error("reverseDigits expects a non-negative integer");
  }
  while (n !== 0) {
    acc = acc * 10 + (n % 10);
    n = Math.floor(n / 10);
  }
  return acc;
}

