export function countChar(s: string, ch: string): number {
  if (ch.length !== 1) {
    throw new Error("ch must be exactly one character");
  }
  let count = 0;
  let index = s.indexOf(ch);
  while (index !== -1) {
    count++;
    index = s.indexOf(ch, index + 1);
  }
  return count;
}

