    const quote = field.indexOf('"');
    const newline = field.indexOf("\n");
    const carriageReturn = field.indexOf("\r");

    if (comma === -1 && quote === -1 && newline === -1 && carriageReturn === -1) {
      rendered[i] = field;
      continue;
    }

    if (quote === -1) {
      rendered[i] = '"' + field + '"';
      continue;
    }

    let escaped = "";
    let start = 0;
